async (page) => {
  // Re-enter reduced motion and prove the JS loop is frozen:
  // two snapshots of the steam canvas 500ms apart must be identical.
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.waitForTimeout(800);
  const frozen = await page.evaluate(() => new Promise(res => {
    const c = document.getElementById('steam');
    const a = c.toDataURL();
    setTimeout(() => res(a === c.toDataURL()), 500);
  }));
  const rmState = await page.evaluate(() => ({
    anims: document.getAnimations().length,
    tilt: document.getElementById('tilt').style.transform || '(cleared)',
    cursorGlow: getComputedStyle(document.getElementById('cursorGlow')).display
  }));
  await page.screenshot({ path: './reduced.png' });
  await page.emulateMedia({ reducedMotion: 'no-preference' });
  // restore it afterwards: confirm the loop resumes
  await page.waitForTimeout(300);
  const resumed = await page.evaluate(() => new Promise(res => {
    const c = document.getElementById('steam');
    const a = c.toDataURL();
    setTimeout(() => res(a !== c.toDataURL()), 500);
  }));
  return { frozen, rmState, resumed };
}

